{{ config(materialized='view') }}

with t0 as (
    select
        partner_id as HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID,
        medical_report as HUB_DOCUMENT_BK__MEDICAL_REPORT,
        member_no as HUB_PARTY_BK__MEMBER_NO,
        contract_id as HUB_POLICY_BK__CONTRACT_ID,
        member_no as HUB_RISK_OBJECT_BK__MEMBER_NO,
        proposal_reject_dtls
    from {{ ref('stg_ec_mem_dtls_extn') }}
    qualify row_number() over (partition by HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, HUB_DOCUMENT_BK__MEDICAL_REPORT, HUB_PARTY_BK__MEMBER_NO, HUB_POLICY_BK__CONTRACT_ID, HUB_RISK_OBJECT_BK__MEMBER_NO order by HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, HUB_DOCUMENT_BK__MEDICAL_REPORT, HUB_PARTY_BK__MEMBER_NO, HUB_POLICY_BK__CONTRACT_ID, HUB_RISK_OBJECT_BK__MEMBER_NO) = 1
),

t1 as (
    select
        nullif('EMP:' || coalesce(nullif(trim(POLICY_NO),''),'') || '#' || coalesce(nullif(trim(EMP_CODE),''),''), 'EMP:#') as HUB_PARTY_BK__EMP_POLICY_NO_EMP_CODE,
        nullif(trim(POLICY_NO),'') as HUB_POLICY_BK__POLICY_NO,
        disclaimer_indicator,
        effective_date,
        mail_indicator,
        status
    from {{ ref('stg_hat_pol_emp_map') }}
    qualify row_number() over (partition by HUB_PARTY_BK__EMP_POLICY_NO_EMP_CODE, HUB_POLICY_BK__POLICY_NO order by HUB_PARTY_BK__EMP_POLICY_NO_EMP_CODE, HUB_POLICY_BK__POLICY_NO) = 1
),

t2 as (
    select
        clid as HUB_CLAIM_BK__CLID,
        imd_code as HUB_DISTRIBUTION_CHANNEL_BK__IMD_CODE,
        bank_ac_no as HUB_FINANCIAL_ACCOUNT_BK__BANK_AC_NO,
        utr_no as HUB_FINANCIAL_TRANSACTION_BK__UTR_NO,
        location_code as HUB_LOCATION_BK__LOCATION_CODE,
        locationcode as HUB_LOCATION_BK__LOCATIONCODE,
        orphan_loc as HUB_LOCATION_BK__ORPHAN_LOC,
        policy_location as HUB_LOCATION_BK__POLICY_LOCATION,
        risk_location as HUB_LOCATION_BK__RISK_LOCATION,
        claim_no as HUB_LOSS_EVENT_BK__CLAIM_NO,
        hospital_id as HUB_PARTY_BK__HOSPITAL_ID,
        cheque_no as HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO,
        policy as HUB_POLICY_BK__POLICY,
        eligible_room_category_h,
        eligible_room_rent_h
    from {{ ref('stg_hm_hcm_extract') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__CLID, HUB_DISTRIBUTION_CHANNEL_BK__IMD_CODE, HUB_FINANCIAL_ACCOUNT_BK__BANK_AC_NO, HUB_FINANCIAL_TRANSACTION_BK__UTR_NO, HUB_LOSS_EVENT_BK__CLAIM_NO, HUB_PARTY_BK__HOSPITAL_ID, HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO, HUB_POLICY_BK__POLICY order by HUB_CLAIM_BK__CLID, HUB_DISTRIBUTION_CHANNEL_BK__IMD_CODE, HUB_FINANCIAL_ACCOUNT_BK__BANK_AC_NO, HUB_FINANCIAL_TRANSACTION_BK__UTR_NO, HUB_LOSS_EVENT_BK__CLAIM_NO, HUB_PARTY_BK__HOSPITAL_ID, HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO, HUB_POLICY_BK__POLICY) = 1
),

t3 as (
    select
        hosid as HUB_AGREEMENT_BK__HOSID,
        distribution_partner as HUB_DISTRIBUTION_CHANNEL_BK__DISTRIBUTION_PARTNER,
        hosid as HUB_PARTY_BK__HOSID,
        legal_const
    from {{ ref('stg_hm_hospital_master_extn') }}
    qualify row_number() over (partition by HUB_AGREEMENT_BK__HOSID, HUB_DISTRIBUTION_CHANNEL_BK__DISTRIBUTION_PARTNER, HUB_PARTY_BK__HOSID order by HUB_AGREEMENT_BK__HOSID, HUB_DISTRIBUTION_CHANNEL_BK__DISTRIBUTION_PARTNER, HUB_PARTY_BK__HOSID) = 1
),

t4 as (
    select
        loginname as HUB_PARTY_BK__LOGINNAME,
        policy_ref as HUB_POLICY_BK__POLICY_REF,
        loginname
    from {{ ref('stg_hm_policy_usermapping') }}
    qualify row_number() over (partition by HUB_PARTY_BK__LOGINNAME, HUB_POLICY_BK__POLICY_REF order by HUB_PARTY_BK__LOGINNAME, HUB_POLICY_BK__POLICY_REF) = 1
),

t5 as (
    select
        nullif('ADDRID:' || nullif(trim(MAILING_ADDRESS_ID),''), 'ADDRID:') as HUB_LOCATION_BK__ADDRID_MAILING_ADDRESS_ID,
        nullif('PARTNER:' || nullif(trim(PARTNER_ID),''), 'PARTNER:') as HUB_PARTY_BK__PARTNER_PARTNER_ID,
        nullif(trim(CONTRACT_ID),'') as HUB_POLICY_BK__CONTRACT_ID,
        ip_no
    from {{ ref('stg_ocp_interested_parties') }}
    qualify row_number() over (partition by HUB_LOCATION_BK__ADDRID_MAILING_ADDRESS_ID, HUB_PARTY_BK__PARTNER_PARTNER_ID, HUB_POLICY_BK__CONTRACT_ID, ip_no order by HUB_LOCATION_BK__ADDRID_MAILING_ADDRESS_ID, HUB_PARTY_BK__PARTNER_PARTNER_ID, HUB_POLICY_BK__CONTRACT_ID, ip_no) = 1
),

t6 as (
    select
        md5(normalise(upper(nullif(trim( coalesce(ADDRESS_LINE1,'') || '|' || coalesce(CORP_CITY,'') || '|' || coalesce(CORP_PIN,'') ), '||')))) as HUB_LOCATION_BK__ADDRESS_LINE1_CORP_CITY_CORP_PIN,
        md5(normalise(upper(nullif(trim( coalesce(PH_ADDRESS,'') ), '')))) as HUB_LOCATION_BK__PH_ADDRESS,
        md5(normalise(upper(nullif(trim( coalesce(PP_ADDRESS,'') ), '')))) as HUB_LOCATION_BK__PP_ADDRESS,
        nullif('EMP:' || nullif(trim(RM_CODE),''), 'EMP:') as HUB_PARTY_BK__EMP_RM_CODE,
        nullif(trim(CORPORATE_ID),'') as HUB_PARTY_BK__CORPORATE_ID,
        nullif(trim(IMD_CODE),'') as HUB_PARTY_BK__IMD_CODE,
        nullif(trim(PH_ID),'') as HUB_PARTY_BK__PH_ID,
        nullif(trim(PP_ID),'') as HUB_PARTY_BK__PP_ID,
        nullif(trim(SUBIMD_CODE),'') as HUB_PARTY_BK__SUBIMD_CODE,
        nullif(trim(POLICY_NO),'') as HUB_POLICY_BK__POLICY_NO,
        nullif(trim(SCRUTINY_NO),'') as HUB_PROPOSAL_BK__SCRUTINY_NO,
        nullif(trim(QUOTATION_NO),'') as HUB_QUOTE_BK__QUOTATION_NO,
        corporate_name,
        enrollmemt_status,
        req_no,
        smesize,
        smetype,
        sme_yn
    from {{ ref('stg_enroll_pol_dtls') }}
    qualify row_number() over (partition by HUB_POLICY_BK__POLICY_NO, HUB_PROPOSAL_BK__SCRUTINY_NO, HUB_QUOTE_BK__QUOTATION_NO order by HUB_POLICY_BK__POLICY_NO, HUB_PROPOSAL_BK__SCRUTINY_NO, HUB_QUOTE_BK__QUOTATION_NO) = 1
),

t7 as (
    select
        scrutiny_no as HUB_ASSESSMENT_BK__SCRUTINY_NO,
        branch as HUB_ORG_UNIT_BK__BRANCH,
        department as HUB_ORG_UNIT_BK__DEPARTMENT,
        policy_no as HUB_POLICY_BK__POLICY_NO,
        prev_pol_ref as HUB_POLICY_BK__PREV_POL_REF,
        reg_no as HUB_POLICY_BK__REG_NO,
        product as HUB_PRODUCT_BK__PRODUCT,
        quote_ref_no as HUB_PROPOSAL_BK__QUOTE_REF_NO,
        quote_sub_no as HUB_QUOTE_BK__QUOTE_SUB_NO,
        flag_sme,
        industry_profile,
        industry_profile_gpg
    from {{ ref('stg_grp_hlt_dtls') }}
    qualify row_number() over (partition by HUB_ASSESSMENT_BK__SCRUTINY_NO, HUB_PRODUCT_BK__PRODUCT, HUB_PROPOSAL_BK__QUOTE_REF_NO, HUB_QUOTE_BK__QUOTE_SUB_NO order by HUB_ASSESSMENT_BK__SCRUTINY_NO, HUB_PRODUCT_BK__PRODUCT, HUB_PROPOSAL_BK__QUOTE_REF_NO, HUB_QUOTE_BK__QUOTE_SUB_NO) = 1
),

t8 as (
    select
        nullif(trim(CLAIM_ID),'') as HUB_CLAIM_BK__CLAIM_ID,
        nullif('FIR:' || nullif(trim(FIR_NO),''), 'FIR:') as HUB_DOCUMENT_BK__FIR_FIR_NO,
        nullif('OMNI_INWARD:' || nullif(trim(OMNI_INWARD_NO),''), 'OMNI_INWARD:') as HUB_DOCUMENT_BK__OMNI_INWARD_OMNI_INWARD_NO,
        nullif('HEALTHCARD:' || nullif(trim(INSURED_CARD_NO),''), 'HEALTHCARD:') as HUB_PARTY_BK__HEALTHCARD_INSURED_CARD_NO,
        nullif('HEALTHCARD:' || nullif(trim(PATIENT_ID_CARD),''), 'HEALTHCARD:') as HUB_PARTY_BK__HEALTHCARD_PATIENT_ID_CARD,
        nullif('HOSPID:' || nullif(trim(HOS_ID),''), 'HOSPID:') as HUB_PARTY_BK__HOSPID_HOS_ID,
        inserted_by
    from {{ ref('stg_hm_preauth_request') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__CLAIM_ID order by HUB_CLAIM_BK__CLAIM_ID) = 1
)

select
    t3.HUB_AGREEMENT_BK__HOSID as HUB_AGREEMENT_BK,
    t7.HUB_ASSESSMENT_BK__SCRUTINY_NO as HUB_ASSESSMENT_BK,
    coalesce(t2.HUB_CLAIM_BK__CLID, t8.HUB_CLAIM_BK__CLAIM_ID) as HUB_CLAIM_BK,
    coalesce(t0.HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, t2.HUB_DISTRIBUTION_CHANNEL_BK__IMD_CODE, t3.HUB_DISTRIBUTION_CHANNEL_BK__DISTRIBUTION_PARTNER) as HUB_DISTRIBUTION_CHANNEL_BK,
    t0.HUB_DOCUMENT_BK__MEDICAL_REPORT as HUB_DOCUMENT_BK,
    t2.HUB_FINANCIAL_ACCOUNT_BK__BANK_AC_NO as HUB_FINANCIAL_ACCOUNT_BK,
    t2.HUB_FINANCIAL_TRANSACTION_BK__UTR_NO as HUB_FINANCIAL_TRANSACTION_BK,
    t5.HUB_LOCATION_BK__ADDRID_MAILING_ADDRESS_ID as HUB_LOCATION_BK,
    t2.HUB_LOSS_EVENT_BK__CLAIM_NO as HUB_LOSS_EVENT_BK,
    coalesce(t0.HUB_PARTY_BK__MEMBER_NO, t1.HUB_PARTY_BK__EMP_POLICY_NO_EMP_CODE, t2.HUB_PARTY_BK__HOSPITAL_ID, t3.HUB_PARTY_BK__HOSID, t4.HUB_PARTY_BK__LOGINNAME, t5.HUB_PARTY_BK__PARTNER_PARTNER_ID) as HUB_PARTY_BK,
    t2.HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO as HUB_PAYMENT_INSTRUMENT_BK,
    coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__POLICY_NO, t2.HUB_POLICY_BK__POLICY, t4.HUB_POLICY_BK__POLICY_REF, t5.HUB_POLICY_BK__CONTRACT_ID, t6.HUB_POLICY_BK__POLICY_NO) as HUB_POLICY_BK,
    t7.HUB_PRODUCT_BK__PRODUCT as HUB_PRODUCT_BK,
    coalesce(t6.HUB_PROPOSAL_BK__SCRUTINY_NO, t7.HUB_PROPOSAL_BK__QUOTE_REF_NO) as HUB_PROPOSAL_BK,
    coalesce(t6.HUB_QUOTE_BK__QUOTATION_NO, t7.HUB_QUOTE_BK__QUOTE_SUB_NO) as HUB_QUOTE_BK,
    t0.HUB_RISK_OBJECT_BK__MEMBER_NO as HUB_RISK_OBJECT_BK,
    t2.HUB_LOCATION_BK__LOCATION_CODE as T2__HUB_LOCATION_BK__LOCATION_CODE,
    t2.HUB_LOCATION_BK__LOCATIONCODE as T2__HUB_LOCATION_BK__LOCATIONCODE,
    t2.HUB_LOCATION_BK__ORPHAN_LOC as T2__HUB_LOCATION_BK__ORPHAN_LOC,
    t2.HUB_LOCATION_BK__POLICY_LOCATION as T2__HUB_LOCATION_BK__POLICY_LOCATION,
    t2.HUB_LOCATION_BK__RISK_LOCATION as T2__HUB_LOCATION_BK__RISK_LOCATION,
    t6.HUB_LOCATION_BK__ADDRESS_LINE1_CORP_CITY_CORP_PIN as T6__HUB_LOCATION_BK__ADDRESS_LINE1_CORP_CITY_CORP_PIN,
    t6.HUB_LOCATION_BK__PH_ADDRESS as T6__HUB_LOCATION_BK__PH_ADDRESS,
    t6.HUB_LOCATION_BK__PP_ADDRESS as T6__HUB_LOCATION_BK__PP_ADDRESS,
    t6.HUB_PARTY_BK__EMP_RM_CODE as T6__HUB_PARTY_BK__EMP_RM_CODE,
    t6.HUB_PARTY_BK__CORPORATE_ID as T6__HUB_PARTY_BK__CORPORATE_ID,
    t6.HUB_PARTY_BK__IMD_CODE as T6__HUB_PARTY_BK__IMD_CODE,
    t6.HUB_PARTY_BK__PH_ID as T6__HUB_PARTY_BK__PH_ID,
    t6.HUB_PARTY_BK__PP_ID as T6__HUB_PARTY_BK__PP_ID,
    t6.HUB_PARTY_BK__SUBIMD_CODE as T6__HUB_PARTY_BK__SUBIMD_CODE,
    t7.HUB_ORG_UNIT_BK__BRANCH as T7__HUB_ORG_UNIT_BK__BRANCH,
    t7.HUB_ORG_UNIT_BK__DEPARTMENT as T7__HUB_ORG_UNIT_BK__DEPARTMENT,
    t7.HUB_POLICY_BK__POLICY_NO as T7__HUB_POLICY_BK__POLICY_NO,
    t7.HUB_POLICY_BK__PREV_POL_REF as T7__HUB_POLICY_BK__PREV_POL_REF,
    t7.HUB_POLICY_BK__REG_NO as T7__HUB_POLICY_BK__REG_NO,
    t8.HUB_DOCUMENT_BK__FIR_FIR_NO as T8__HUB_DOCUMENT_BK__FIR_FIR_NO,
    t8.HUB_DOCUMENT_BK__OMNI_INWARD_OMNI_INWARD_NO as T8__HUB_DOCUMENT_BK__OMNI_INWARD_OMNI_INWARD_NO,
    t8.HUB_PARTY_BK__HEALTHCARD_INSURED_CARD_NO as T8__HUB_PARTY_BK__HEALTHCARD_INSURED_CARD_NO,
    t8.HUB_PARTY_BK__HEALTHCARD_PATIENT_ID_CARD as T8__HUB_PARTY_BK__HEALTHCARD_PATIENT_ID_CARD,
    t8.HUB_PARTY_BK__HOSPID_HOS_ID as T8__HUB_PARTY_BK__HOSPID_HOS_ID,
    t0.proposal_reject_dtls as DECLINE_REASON,
    t1.disclaimer_indicator as DISCLAIMER_ACCEPTED_INDICATOR,
    t6.corporate_name as GROUP_NAME,
    coalesce(t7.industry_profile, t7.industry_profile_gpg) as INDUSTRY_DESCRIPTION,
    t3.legal_const as LEGAL_CONSTITUTION_CODE,
    coalesce(t8.inserted_by, t4.loginname) as LOGIN_IDENTIFIER,
    t6.smesize as MSME_CATEGORY,
    t6.smetype as MSME_ENTERPRISE_TYPE,
    coalesce(t6.sme_yn, t7.flag_sme) as MSME_INDICATOR,
    t2.eligible_room_rent_h as PER_DAY_LIMIT,
    t1.mail_indicator as PREFERRED_CHANNEL_CODE,
    t6.enrollmemt_status as PROPOSAL_STATUS,
    t1.effective_date as ROLE_EFFECTIVE_DATE,
    t5.ip_no as ROLE_SEQUENCE,
    t1.status as ROLE_STATUS,
    t2.eligible_room_category_h as ROOM_CATEGORY_LINKAGE,
    t6.req_no as SERVICING_REQUEST_NUMBER
from t0
full outer join t1 on t1.HUB_PARTY_BK__EMP_POLICY_NO_EMP_CODE = t0.HUB_PARTY_BK__MEMBER_NO
full outer join t2 on t2.HUB_PARTY_BK__HOSPITAL_ID = coalesce(t0.HUB_PARTY_BK__MEMBER_NO, t1.HUB_PARTY_BK__EMP_POLICY_NO_EMP_CODE)
full outer join t3 on t3.HUB_PARTY_BK__HOSID = coalesce(t0.HUB_PARTY_BK__MEMBER_NO, t1.HUB_PARTY_BK__EMP_POLICY_NO_EMP_CODE, t2.HUB_PARTY_BK__HOSPITAL_ID)
full outer join t4 on t4.HUB_PARTY_BK__LOGINNAME = coalesce(t0.HUB_PARTY_BK__MEMBER_NO, t1.HUB_PARTY_BK__EMP_POLICY_NO_EMP_CODE, t2.HUB_PARTY_BK__HOSPITAL_ID, t3.HUB_PARTY_BK__HOSID)
full outer join t5 on t5.HUB_PARTY_BK__PARTNER_PARTNER_ID = coalesce(t0.HUB_PARTY_BK__MEMBER_NO, t1.HUB_PARTY_BK__EMP_POLICY_NO_EMP_CODE, t2.HUB_PARTY_BK__HOSPITAL_ID, t3.HUB_PARTY_BK__HOSID, t4.HUB_PARTY_BK__LOGINNAME)
full outer join t6 on t6.HUB_POLICY_BK__POLICY_NO = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__POLICY_NO, t2.HUB_POLICY_BK__POLICY, t4.HUB_POLICY_BK__POLICY_REF, t5.HUB_POLICY_BK__CONTRACT_ID)
full outer join t7 on t7.HUB_PROPOSAL_BK__QUOTE_REF_NO = t6.HUB_PROPOSAL_BK__SCRUTINY_NO
full outer join t8 on t8.HUB_CLAIM_BK__CLAIM_ID = t2.HUB_CLAIM_BK__CLID
